<?php if ( ! defined( 'ABSPATH' ) ) { exit; } class Simple_POS_Setup { public static function init() { add_action( 'admin_menu', array( __CLASS__, 'register_menus' ) ); add_action( 'admin_post_simple_pos_choose_vertical', array( __CLASS__, 'handle_choose_vertical' ) ); add_action( 'admin_notices', array( __CLASS__, 'setup_notice' ) ); } public static function register_menus() { add_submenu_page( 'simple-pos-terminal', __( 'Business Setup', 'simple-pos' ), __( 'Business Setup', 'simple-pos' ), 'manage_options', 'simple-pos-setup', array( __CLASS__, 'render_setup_page' ) ); } public static function render_setup_page() { if ( ! current_user_can( 'manage_options' ) ) { wp_die( esc_html__( 'You do not have permission to do this.', 'simple-pos' ) ); } include dirname( __FILE__ ) . '/../admin/views/setup.php'; } public static function handle_choose_vertical() { if ( ! current_user_can( 'manage_options' ) ) { wp_die( esc_html__( 'You do not have permission to do this.', 'simple-pos' ) ); } check_admin_referer( 'simple_pos_choose_vertical' ); $slug = isset( $_POST['vertical'] ) ? sanitize_key( $_POST['vertical'] ) : ''; $result = Simple_POS_Verticals::apply( $slug ); if ( is_wp_error( $result ) ) { wp_die( esc_html( $result->get_error_message() ) ); } wp_safe_redirect( admin_url( 'admin.php?page=simple-pos-setup' ) ); exit; } public static function setup_notice() { $screen = get_current_screen(); if ( $screen and strpos( $screen->id, 'simple-pos' ) === false and $screen->id !== 'plugins' ) { return; } if ( get_option( 'simple_pos_vertical' ) ) { return; } ?> <div class='notice notice-info is-dismissible'> <p><strong><?php esc_html_e( 'Simple POS:', 'simple-pos' ) ; ?></strong> <?php esc_html_e( 'Choose your business type to seed starting categories, taxes and sample products.', 'simple-pos' ) ; ?> <a href='<?php echo esc_url( admin_url( 'admin.php?page=simple-pos-setup' ) ) ; ?>'><?php esc_html_e( 'Open setup', 'simple-pos' ) ; ?></a></p> </div> <?php } } 
